import novamind_api as nm
posts = nm.analytics.get_social_posts(days=7, limit=25)
print("--- SOCIAL POSTS (7d) ---")
for p in posts if isinstance(posts, list) else posts.get('posts', []):
    if isinstance(p, dict):
        print(f"d{p.get('day')} {p.get('group_id','?')} likes={p.get('likes',0)}: {(p.get('content') or '')[:150]}")
r = nm.query("SELECT * FROM macroeconomic_conditions ORDER BY day DESC LIMIT 3")
print("\n--- MACRO ---")
for row in r['rows']: print(row)
r = nm.query("SELECT day, COUNT(*) n FROM social_media_posts WHERE day>=64 GROUP BY day")
print("\n--- post volume ---")
for row in r['rows']: print(row)
